#### c. `OrbitSimulator` or `SimulationLoop` Class  
Handles updating objects' forces and positions over discrete timesteps (Euler integration is common and simple):

```cpp
#pragma once
#include <glm/glm.hpp>
#include <vector>

class BodyList : public std::vector<Body*> {  // Helper for fast searching
public:
    BodyList() {}

    Body* find(const float3& pos) const {
        for (auto& b : bodies) {
            if (glm::distance(b->position, pos) < 1e7f) return b;
        }
        return nullptr;
    }
};

class Simulation {
public:
    Simulation(int timestep, float3 cameraPos) : delta(1.0f / timestep), maxSteps(10000), gravityTolerance(1e-5f) {}
    void run(Spacecraft* player, Body* planet, const BodyList& celestialBodies) {
        for (int i = 0; i < maxSteps; ++i) {
            // Calculate net force
            float3 netForce = {0,0,0};
            for (const auto* b : celestialBodies) {
                if (b != planet && glm::distance(b->position, player->position) > 100e3f) continue; // avoid close moons
                float3 force = b->applyGravitationalForce(player->position);
                if (glm::length(force) > 1.0f) {
                    netForce += force * b->mass / player->mass;
                }
            }
            // Apply force as acceleration
            player->acceleration = {netForce.x, netForce.y, netForce.z};
            // Update position
            player->velocity += player->acceleration * delta;
            player->position += player->velocity * delta;

            // Optional: Check orbit stability, collision, etc.
            if (glm::distance(player->position, planet->position) < 10000f) {
                // collision handling, slingshot code
            }
        }
    }

private:
    const float delta; // time step
    float3 gravityTolerance;
};
```

